<script setup lang="ts">
import {ref} from 'vue'; import {requirementRepository} from '../../services/requirementRepository';
const props=defineProps<{requirementId:string;status:string}>(); const emit=defineEmits<{changed:[]}>(); const reason=ref(''); const action=ref<'hold'|'reject'|''>(''); const saving=ref(false); const error=ref(''); const open=(value:'hold'|'reject')=>{action.value=value;reason.value='';error.value=''}; const submit=async()=>{if(!reason.value.trim()){error.value='请输入操作原因';return;}saving.value=true;error.value='';try{await requirementRepository.transition(props.requirementId,{action:action.value,reason:reason.value.trim()});action.value='';emit('changed')}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{saving.value=false}};
</script>
<template><div class="requirement-actions"><button v-if="status==='待处理'" class="secondary" @click="open('hold')">搁置</button><button v-if="status==='待处理'||status==='已搁置'" class="secondary" @click="open('reject')">驳回</button><div v-if="action" class="action-editor"><textarea v-model="reason" rows="2" placeholder="请输入操作原因"/><p v-if="error" class="form-feedback error">{{error}}</p><button class="primary" :disabled="saving" @click="submit">{{saving?'提交中…':'确认'}}</button><button class="secondary" @click="action=''">取消</button></div></div></template>
